select 'bbbb0002-0000-4000-8000-000000000019', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"When your browser loads a page, which side sends the request and which sends the response?","options":["the server requests, the client responds","the client requests, the server responds","both send requests at once","neither  - the page is stored locally"],"answer":1,"explanation":"The client (browser) sends a request; the server sends back a response  - see ''How the web works''."},{"prompt":"Which HTTP method is normally used to fetch a resource without changing it?","options":["POST","DELETE","GET","PUT"],"answer":2,"explanation":"GET is the read method; it should not modify server state  - see ''What an API is''."},{"prompt":"An HTTP status code in the 200 range means...","options":["the client made an error","the server crashed","success","the resource moved"],"answer":2,"explanation":"2xx codes signal success; 4xx are client errors and 5xx are server errors."},{"prompt":"In REST, a URL like /users/42 most naturally represents...","options":["a function call named users","a single user resource with id 42","a database password","an HTML template"],"answer":1,"explanation":"REST models nouns as resources; /users/42 is the user whose id is 42  - see ''Designing resources and endpoints''."},{"prompt":"Which format is most commonly used to send structured data in an API request or response body?","options":["JSON","PNG","CSV only","plain prose"],"answer":0,"explanation":"JSON is the standard interchange format for request and response bodies."},{"prompt":"CRUD stands for the four basic operations on stored data. Which list is correct?","options":["Copy, Read, Undo, Delete","Create, Read, Update, Delete","Cache, Route, Update, Deploy","Connect, Run, Use, Drop"],"answer":1,"explanation":"Create, Read, Update, Delete  - the four things you do to persisted records."},{"prompt":"A token sent in an Authorization header is mainly used to...","options":["compress the response","prove who the caller is","speed up the database","format the JSON"],"answer":1,"explanation":"Auth tokens carry identity so the server can authenticate the caller  - see ''Authentication and authorization''."},{"prompt":"If a client sends a malformed request the server cannot process, the most appropriate status is...","options":["200 OK","301 Moved","400 Bad Request","500 Internal Server Error"],"answer":2,"explanation":"400 tells the client its own request was invalid; 500 would wrongly blame the server."}]}'::jsonb, null, 10),
  (2, 'How the web works: clients, servers, HTTP', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Trace a single web interaction from client to server and back, name the common HTTP methods, and read a status code well enough to know who is at fault. Warm-up: from the diagnostic, which side sends the request?"},{"heading":"The idea","text":"The web runs on a request-response cycle. A client (a browser, a mobile app, or another program) opens a connection to a server and sends an HTTP request. The request has a method (the verb), a path (which resource), headers (metadata like content type and authorization), and sometimes a body (data being sent). The server does work and returns an HTTP response: a status code, response headers, and usually a body. HTTP is stateless  - each request stands alone, so any memory of who you are must be carried explicitly, usually in a header. The core methods map to intentions: GET reads, POST creates, PUT and PATCH update, and DELETE removes. Status codes come in families: 2xx success, 3xx redirection, 4xx the client erred, 5xx the server erred."},{"heading":"Worked examples","text":"A read looks like: GET /articles/7 HTTP/1.1 with a Host header and no body. The server answers 200 OK and a JSON body describing article 7. A create looks like: POST /articles with a body {\"title\": \"Hello\"}; a healthy server replies 201 Created and includes the new resource''s location. Asking for something absent, GET /articles/9999, returns 404 Not Found  - a 4xx, so the client asked for the wrong thing. If the server''s own code throws while handling GET /articles/7, it returns 500 Internal Server Error  - a 5xx, the server''s fault, not yours. A permanent move returns 301 with a Location header telling the client where to go next."},{"heading":"Your turn","text":"1) Which method would you use to delete comment 12? 2) A response comes back 403 Forbidden  - is the problem on the client or server side? 3) What status best fits creating a new order successfully? 4) Name the four parts of an HTTP request. 5) Why must a token be re-sent on every request? Answers: 1) DELETE /comments/12. 2) Client side  - 4xx means the request was refused (here, not allowed). 3) 201 Created. 4) Method, path, headers, and (optionally) body. 5) Because HTTP is stateless  - the server keeps no memory of the previous request, so identity must ride along each time."},{"heading":"Common mistakes & exit ticket","text":"Mistake: using GET to change data  - GET should be safe and repeatable, so use POST, PUT, or DELETE for changes. Mistake: returning 200 for an error so the body has to explain the failure; let the status code carry that signal. Exit: (a) Which status family means the client made the mistake? (b) Which method creates a resource? Answers: 4xx; POST."}]}'::jsonb, 'A request always names a method and a path (GET /users); a response always carries a status code (200)  - keep those two vocabularies separate.', 14),
  (3, 'What an API is, and the REST principles', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what an API is in plain terms and list the REST principles that shape a well-behaved HTTP API. Warm-up: what does the R in CRUD read from?"},{"heading":"The idea","text":"An API (application programming interface) is a contract: it defines the requests a program will accept and the responses it promises in return, so two programs can cooperate without knowing each other''s internals. A web API exposes that contract over HTTP. REST (Representational State Transfer) is the most common style for web APIs. Its guiding principles: model everything as resources named by URLs; use the HTTP methods for their intended verbs (GET reads, POST creates, and so on); keep interactions stateless, so each request carries everything the server needs; return representations, usually JSON, rather than server internals; and make identical safe requests repeatable. A key idea is idempotency: GET, PUT, and DELETE should produce the same end state no matter how many times they are repeated, while POST typically is not idempotent because it creates something new each time."},{"heading":"Worked examples","text":"A weather service might publish the contract GET /cities/paris/forecast returns {\"high\": 24, \"low\": 15, \"unit\": \"C\"}. That single line is the API: the request shape and the response shape. Compare two calls: DELETE /users/8 sent twice leaves the same end state (user 8 is gone either way), so DELETE is idempotent. But POST /users sent twice creates two users, so POST is not idempotent. A non-REST design might expose GET /getUserById?id=8 with a verb in the path; the REST version is GET /users/8, letting the method be the verb and the path be the noun."},{"heading":"Your turn","text":"1) In one sentence, what is an API? 2) Is PUT /users/8 idempotent? 3) Rewrite GET /deleteArticle?id=3 as a RESTful call. 4) Which REST principle explains why the server keeps no session in memory? 5) Name the usual representation format for a REST response. Answers: 1) A contract defining accepted requests and promised responses so programs can cooperate. 2) Yes  - setting user 8 to the same values repeatedly ends in the same state. 3) DELETE /articles/3. 4) Statelessness  - each request carries all it needs. 5) JSON."},{"heading":"Common mistakes & exit ticket","text":"Mistake: putting verbs in the path (/createUser) instead of letting the HTTP method be the verb. Mistake: assuming every method is idempotent  - POST usually is not. Exit: (a) What does REST model everything as? (b) Which method is typically not idempotent? Answers: resources named by URLs; POST."}]}'::jsonb, 'REST is a style, not a protocol: it is a set of conventions layered on top of HTTP, not a separate technology you install.', 13),
  (4, 'Designing resources and endpoints', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Turn a real-world domain into a clean set of resource URLs and choose the right method for each endpoint. Warm-up: should a collection of users live at /user or /users?"},{"heading":"The idea","text":"Endpoint design starts by naming the nouns of your domain as resources. A collection is a plural noun (/products); a single member adds an identifier (/products/42). Relationships are shown by nesting a child collection under a parent member (/products/42/reviews). Once the paths exist, the methods give you a full set of operations without inventing new URLs: GET /products lists, POST /products creates, GET /products/42 reads one, PUT or PATCH /products/42 updates, and DELETE /products/42 removes. Filtering, sorting, and paging belong in the query string, not the path: GET /products?category=books&page=2. Keep verbs out of paths and keep names consistent, so a developer can guess an endpoint they have never seen."},{"heading":"Worked examples","text":"Model a blog. Articles: GET /articles (list), POST /articles (create), GET /articles/7 (read one), PATCH /articles/7 (edit), DELETE /articles/7 (remove). Comments belong to an article, so nest them: GET /articles/7/comments and POST /articles/7/comments. Want only published articles, newest first, ten per page? Use the query string: GET /articles?status=published&sort=-created&limit=10. Notice you never needed a path like /getPublishedArticles  - the collection plus a filter expresses it. A poor design mixes styles: /articles, /getComment, /article_delete; a good design stays uniform: /articles, /articles/7/comments."},{"heading":"Your turn","text":"1) Give the endpoint to list all orders. 2) Give the endpoint and method to update customer 30. 3) How would you fetch the line items of order 5? 4) Where do filters like status=open belong  - path or query string? 5) Rewrite /createOrder the RESTful way. Answers: 1) GET /orders. 2) PUT or PATCH /customers/30. 3) GET /orders/5/items. 4) The query string, e.g. /orders?status=open. 5) POST /orders."},{"heading":"Common mistakes & exit ticket","text":"Mistake: encoding actions as paths (/orders/5/cancel is tolerable, but /cancelOrder?id=5 is not RESTful). Mistake: putting filters in the path so every combination needs a new route. Exit: (a) Plural or singular for a collection name? (b) Which method reads a single member? Answers: plural; GET."}]}'::jsonb, 'Name collections with plural nouns (/orders), address one member by id (/orders/5), and nest only to show ownership (/orders/5/items).', 14),
  (5, 'Request and response bodies with JSON', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read and write JSON payloads, set the Content-Type header correctly, and match a request body to the response it should produce. Warm-up: which quote character does JSON require around keys?"},{"heading":"The idea","text":"JSON (JavaScript Object Notation) is a lightweight text format for structured data. Its building blocks are objects ({ } with key-value pairs), arrays ([ ] ordered lists), strings in double quotes, numbers, the booleans true and false, and null. When a client sends a body it declares Content-Type: application/json so the server knows how to parse it. The server likewise labels its response body. A common shape is an envelope: a top-level object with the resource under a key, or the resource itself. Because JSON is just text, both sides must agree on field names and types  - that agreement is part of the API contract. Dates are usually sent as ISO 8601 strings (\"2026-07-20T14:00:00Z\") because JSON has no native date type."},{"heading":"Worked examples","text":"A create request: POST /users with header Content-Type: application/json and body {\"name\": \"Ada\", \"age\": 36, \"active\": true, \"roles\": [\"admin\", \"editor\"]}. Note the string in quotes, the bare number 36, the bare boolean true, and the array of strings. The server responds 201 Created with body {\"id\": 51, \"name\": \"Ada\", \"age\": 36, \"active\": true, \"createdAt\": \"2026-07-20T14:00:00Z\"}  - same fields plus a server-assigned id and timestamp. A list response wraps items in an array: {\"items\": [{\"id\": 1, \"name\": \"Ada\"}, {\"id\": 2, \"name\": \"Lin\"}], \"total\": 2}. Invalid JSON, like a trailing comma in {\"name\": \"Ada\",}, makes the server reply 400 because it cannot parse the body."},{"heading":"Your turn","text":"1) Write a JSON object for a product with a string name ''Pen'', a number price 3, and a boolean inStock true. 2) What header must accompany a JSON request body? 3) How is a date typically represented in JSON? 4) Is [1, 2, 3] an object or an array? 5) Why does {\"a\": 1,} fail to parse? Answers: 1) {\"name\": \"Pen\", \"price\": 3, \"inStock\": true}. 2) Content-Type: application/json. 3) As an ISO 8601 string, e.g. \"2026-07-20T14:00:00Z\". 4) An array. 5) It has a trailing comma after the last pair, which JSON does not allow."},{"heading":"Common mistakes & exit ticket","text":"Mistake: using single quotes or unquoted keys  - JSON demands double quotes around every key and string. Mistake: forgetting Content-Type, so the server parses the body as plain text. Exit: (a) Which two bracket types delimit objects and arrays? (b) What status signals a body the server could not parse? Answers: { } for objects and [ ] for arrays; 400 Bad Request."}]}'::jsonb, 'JSON keys and string values use double quotes; numbers and booleans do not  - and there is no trailing comma after the last item.', 13),
  (6, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Which method should read a resource without changing it?","options":["POST","GET","DELETE","PATCH"],"answer":1,"explanation":"GET is the safe, read-only method."},{"prompt":"A response returns 500 Internal Server Error. The fault most likely lies with...","options":["the client''s request","the server''s own handling","the DNS","the JSON quotes"],"answer":1,"explanation":"5xx codes indicate the server failed while processing an otherwise valid request."},{"prompt":"Which URL best follows REST conventions for reading customer 30?","options":["GET /getCustomer?id=30","GET /customers/30","POST /customer/read/30","GET /customer_read?c=30"],"answer":1,"explanation":"Plural collection plus id, with the method as the verb: GET /customers/30."},{"prompt":"Sending DELETE /users/8 twice leaves the same end state. This property is called...","options":["statelessness","idempotency","pagination","serialization"],"answer":1,"explanation":"Idempotent requests reach the same state no matter how many times they repeat."},{"prompt":"Which header tells the server a request body is JSON?","options":["Accept-Language: en","Content-Type: application/json","Cache-Control: no-store","Host: api.example.com"],"answer":1,"explanation":"Content-Type: application/json declares the body format so the server can parse it."},{"prompt":"Where do filters and paging parameters belong in a REST URL?","options":["in the path segments","in the query string","in the method name","in the status code"],"answer":1,"explanation":"Filtering, sorting, and paging go in the query string, e.g. ?status=open&page=2."}]}'::jsonb, null, 8),
  (7, 'Building a simple backend: routes and handlers', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how a backend maps incoming requests to handler functions, read path parameters, and return a status with a JSON body. Warm-up: which two things together identify a route?"},{"heading":"The idea","text":"A backend server is, at heart, a router plus a set of handlers. When a request arrives, the router compares its method and path against a table of routes. The first route that matches hands control to its handler function. The handler receives the request (path parameters, query string, headers, body), does the work, and returns a response: a status code plus, usually, a JSON body. Path parameters are the variable parts of a route pattern  - in GET /users/:id, the :id captures whatever value appears there. Middleware are functions that run before the handler for cross-cutting jobs like parsing the JSON body, logging, or checking a token, then pass control along. The skill is not any one framework but this shape: match a route, run middleware, call one handler, return one response."},{"heading":"Worked examples","text":"Imagine a tiny route table. GET /health maps to a handler that returns 200 and {\"status\": \"ok\"}. GET /users/:id maps to a handler that reads the id parameter, looks up the user, and returns 200 with the user or 404 if none exists. POST /users maps to a handler that reads the parsed JSON body, creates a user, and returns 201 with the new record. In pseudocode a handler reads like: function getUser(request) { let id = request.params.id; let user = store.find(id); if (!user) return respond(404, {\"error\": \"not found\"}); return respond(200, user); }. A JSON-parsing middleware runs first so request.body is already an object by the time the handler sees it."},{"heading":"Your turn","text":"1) In the route GET /orders/:id, what does :id capture? 2) What two things does a router compare to pick a route? 3) A handler for a missing record should return which status? 4) Name one job commonly done by middleware. 5) How many handlers does a single matched route run? Answers: 1) The variable order id from the actual path, e.g. 5 in /orders/5. 2) The request''s method and path. 3) 404 Not Found. 4) Parsing the JSON body, logging, or checking authentication (any one). 5) Exactly one."},{"heading":"Common mistakes & exit ticket","text":"Mistake: doing body parsing by hand inside every handler instead of once in middleware. Mistake: returning 200 with an error message when the record was missing; return 404. Exit: (a) What captures the variable part of a path? (b) What runs before the handler to parse the body? Answers: a path parameter (like :id); middleware."}]}'::jsonb, 'A route is the pattern (method + path) you match; a handler is the function that runs when it matches  - one route maps to exactly one handler.', 14),
  (8, 'Data persistence with a database (CRUD)', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Map the CRUD operations to both SQL statements and HTTP methods, and explain why user input must never be pasted directly into a query. Warm-up: which HTTP method corresponds to creating a row?"},{"heading":"The idea","text":"A backend keeps data in a database so it survives beyond a single request. A relational database stores records in tables of rows and columns; each table usually has a primary key that uniquely identifies a row. CRUD names the four operations, and they line up cleanly across layers. Create is SQL INSERT, triggered by POST. Read is SELECT, triggered by GET. Update is UPDATE, triggered by PUT or PATCH. Delete is DELETE in both SQL and HTTP. Values from the client must go into queries through parameters (placeholders), never by string concatenation, because concatenating raw input allows an attacker to inject their own SQL. Many teams use an intermediate layer that turns rows into objects so handlers work with records rather than raw query text, but the CRUD mapping underneath is the same."},{"heading":"Worked examples","text":"A POST /users handler runs INSERT INTO users (name, email) VALUES ($1, $2) with the two values bound to the placeholders $1 and $2  - the name and email from the JSON body. GET /users/7 runs SELECT * FROM users WHERE id = $1 with 7 bound in. PATCH /users/7 runs UPDATE users SET email = $1 WHERE id = $2. DELETE /users/7 runs DELETE FROM users WHERE id = $1. The dangerous version, SELECT * FROM users WHERE name = ''\" + input + \"'', lets an input like anything'' OR ''1''=''1 return every row; the parameterized version treats the same input as a harmless literal string. That single habit  - bind, do not concatenate  - prevents SQL injection."},{"heading":"Your turn","text":"1) Which SQL statement backs the Read in CRUD? 2) Which HTTP method maps to INSERT? 3) Why use placeholders instead of pasting input into a query? 4) What column uniquely identifies a row in a table? 5) Which two HTTP methods can back an UPDATE? Answers: 1) SELECT. 2) POST. 3) To prevent SQL injection  - placeholders treat input as data, not executable SQL. 4) The primary key. 5) PUT and PATCH."},{"heading":"Common mistakes & exit ticket","text":"Mistake: building queries by concatenating user input, the classic SQL injection hole. Mistake: forgetting a WHERE clause on UPDATE or DELETE, which changes or removes every row. Exit: (a) What does the D in CRUD map to in SQL? (b) What is the safe way to include user values in a query? Answers: DELETE; bound parameters / placeholders."}]}'::jsonb, 'The four CRUD operations line up with SQL and with HTTP: Create/INSERT/POST, Read/SELECT/GET, Update/UPDATE/PUT, Delete/DELETE/DELETE.', 15),
  (9, 'Authentication and authorization', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish authentication from authorization, describe how tokens and sessions carry identity, and choose the right status for an unauthenticated versus a forbidden request. Warm-up: which question does authorization answer?"},{"heading":"The idea","text":"Authentication establishes who the caller is; authorization decides what that caller may do. Because HTTP is stateless, identity must travel with each request. Two common mechanisms exist. A session stores state on the server: the client logs in, the server creates a session record and hands back a session id in a cookie, and the browser returns that cookie on every request. A token, by contrast, is often self-contained: after login the server issues a signed token (for example a JSON Web Token) that the client sends in an Authorization: Bearer header; the server verifies the signature without a lookup. Two status codes matter here: 401 Unauthorized means ''you are not authenticated  - log in,'' while 403 Forbidden means ''you are authenticated but not allowed to do this.'' Never store passwords in plain text; store a salted hash so a stolen database does not reveal them."},{"heading":"Worked examples","text":"Login: POST /sessions with body {\"email\": \"ada@x.com\", \"password\": \"secret\"}. The server checks the password against a stored salted hash and, on success, returns a token: {\"token\": \"eyJhbGciOi...\"}. Later, GET /account carries Authorization: Bearer eyJhbGciOi...; the server verifies the token and returns Ada''s data. A request to GET /account with no token returns 401 Unauthorized. A request where Ada tries DELETE /users/99 (someone else''s account) is authenticated but not permitted, so it returns 403 Forbidden. With sessions instead, the login response sets a cookie like Set-Cookie: sid=abc123, and the browser sends Cookie: sid=abc123 automatically on the next request."},{"heading":"Your turn","text":"1) Which comes first, authentication or authorization? 2) A logged-in editor tries to reach an admin-only endpoint  - which status fits? 3) Where does a bearer token travel in the request? 4) What status means ''you are not logged in''? 5) How should passwords be stored? Answers: 1) Authentication first, then authorization. 2) 403 Forbidden (authenticated but not allowed). 3) In the Authorization header, as Bearer <token>. 4) 401 Unauthorized. 5) As a salted hash, never in plain text."},{"heading":"Common mistakes & exit ticket","text":"Mistake: returning 403 when the caller simply is not logged in  - that case is 401. Mistake: storing passwords in plain text, so a database breach leaks every account. Exit: (a) Which status means authenticated-but-not-allowed? (b) Which mechanism keeps identity state on the server? Answers: 403 Forbidden; a session."}]}'::jsonb, 'Authentication asks ''who are you?''; authorization asks ''are you allowed to do this?''  - you authenticate first, then authorize.', 14),
  (10, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"In a backend, the function that runs when a route matches is called the...","options":["router","handler","socket","schema"],"answer":1,"explanation":"The router matches the request; the handler is the function it invokes."},{"prompt":"The safe way to include a user-supplied value in a SQL query is to...","options":["concatenate it into the string","use a bound parameter / placeholder","uppercase it first","store it in a cookie"],"answer":1,"explanation":"Placeholders treat input as data, preventing SQL injection."},{"prompt":"CRUD''s Update most directly corresponds to which SQL statement?","options":["SELECT","INSERT","UPDATE","DROP"],"answer":2,"explanation":"Update maps to the SQL UPDATE statement, driven by PUT or PATCH."},{"prompt":"A request arrives with no credentials at all. The correct status is...","options":["200 OK","401 Unauthorized","403 Forbidden","500 Internal Server Error"],"answer":1,"explanation":"401 means the caller is not authenticated and should log in."},{"prompt":"A bearer token is normally sent to the server in the...","options":["query string","Authorization header","response body","status line"],"answer":1,"explanation":"Tokens travel in the Authorization header as ''Bearer <token>''."},{"prompt":"Passwords in a user table should be stored as...","options":["plain text for easy checks","a salted hash","base64 of the password","the user''s email"],"answer":1,"explanation":"A salted hash means a stolen database does not reveal the original passwords."}]}'::jsonb, null, 8),
  (11, 'Input validation and error handling', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Validate incoming data, return the right status for each kind of failure, and design a consistent error response body. Warm-up: which status marks a request the server understood but found invalid?"},{"heading":"The idea","text":"Never trust the client. Every request body, query parameter, and path segment should be validated at the boundary before your logic touches it: required fields present, types correct, values within range, strings within length. When validation fails, return a 4xx status and a body that names what went wrong, so the caller can fix it. Distinguish the cases: 400 Bad Request for malformed or invalid input, 401 for missing authentication, 403 for a forbidden action, 404 for a resource that does not exist, 409 Conflict for a duplicate or version clash, and 422 Unprocessable Entity when the syntax is fine but the values fail business rules. For genuine server faults, return 5xx and log the details, but never leak stack traces or database internals to the client. A consistent error envelope  - for example {\"error\": {\"code\": ..., \"message\": ..., \"fields\": ...}}  - lets clients handle failures uniformly."},{"heading":"Worked examples","text":"POST /users with body {\"name\": \"\", \"age\": -3} should fail validation: name is empty and age is negative. Return 422 with {\"error\": {\"message\": \"validation failed\", \"fields\": {\"name\": \"required\", \"age\": \"must be >= 0\"}}}. A request to register an email that already exists returns 409 Conflict with {\"error\": {\"message\": \"email already registered\"}}. A body that is not even valid JSON returns 400. If the database connection drops mid-request, catch the error, log it internally, and return 500 with a bland {\"error\": {\"message\": \"internal error\"}}  - no stack trace. Notice each failure has a distinct, honest status, and the body shape is the same envelope every time."},{"heading":"Your turn","text":"1) Which status fits input that parses but breaks a business rule (age must be positive)? 2) A new record collides with an existing unique email  - which status? 3) Should a 500 response include the database stack trace? 4) Where should validation happen relative to your business logic? 5) Name two things worth validating on an incoming field. Answers: 1) 422 Unprocessable Entity (400 is also defensible for invalid input). 2) 409 Conflict. 3) No  - log it internally and return a generic message. 4) At the boundary, before the logic runs. 5) Presence (required), type, range, and length are all valid answers."},{"heading":"Common mistakes & exit ticket","text":"Mistake: trusting client input and letting bad data reach the database. Mistake: leaking internal error details to callers, which both confuses them and helps attackers. Exit: (a) Which status suits a duplicate-resource conflict? (b) What should a 5xx body avoid exposing? Answers: 409 Conflict; internal details like stack traces or query text."}]}'::jsonb, 'Validate at the boundary: check every incoming field before it reaches your logic, and return one clear error shape when a check fails.', 14),
  (12, 'API security and rate limiting basics', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the core defenses every public API needs and explain how rate limiting protects a backend. Warm-up: which status tells a caller they have sent too many requests?"},{"heading":"The idea","text":"A public endpoint is exposed to everyone, so security is layered. Always serve over HTTPS so credentials and data are encrypted in transit. Authenticate and authorize every protected request, as covered earlier. Validate all input to block injection and malformed data. Send only the fields the client needs, so responses do not leak internal columns. Rate limiting caps how many requests a single client (by token, key, or IP) may make in a time window  - say 100 requests per minute  - to blunt abuse, brute-force login attempts, and accidental floods. When a client exceeds the limit, the server returns 429 Too Many Requests, often with a Retry-After header telling it when to try again. Related headers advertise the budget: X-RateLimit-Limit, X-RateLimit-Remaining, and X-RateLimit-Reset. None of these replaces the others; security is the sum of the layers."},{"heading":"Worked examples","text":"A login endpoint allows 5 attempts per minute per IP to slow password guessing. The sixth attempt in that minute returns 429 Too Many Requests with header Retry-After: 45, meaning wait 45 seconds. A healthy response under the limit might include X-RateLimit-Limit: 100 and X-RateLimit-Remaining: 87, so a well-behaved client can pace itself. Serving the API only over HTTPS means a network eavesdropper sees ciphertext, not the bearer token. And returning {\"id\": 7, \"name\": \"Ada\"} rather than the full row keeps an internal column like password_hash from ever reaching the wire. Each measure closes a different door."},{"heading":"Your turn","text":"1) What status signals that a client has exceeded its rate limit? 2) Which header tells the client how long to wait before retrying? 3) Why serve an API over HTTPS? 4) Give one reason to rate-limit a login endpoint specifically. 5) Why return a subset of columns rather than the whole database row? Answers: 1) 429 Too Many Requests. 2) Retry-After. 3) To encrypt credentials and data in transit so eavesdroppers cannot read them. 4) To slow brute-force password guessing. 5) To avoid leaking sensitive internal fields like a password hash."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating one measure as sufficient  - HTTPS alone does not stop abuse, and rate limiting alone does not encrypt. Mistake: returning whole rows so private columns leak. Exit: (a) Which status means too many requests? (b) Which header advertises remaining quota? Answers: 429; X-RateLimit-Remaining."}]}'::jsonb, 'Rate limiting counts requests per client per window; when the count is exceeded, respond 429 Too Many Requests rather than doing the work.', 14),
  (13, 'Testing and documenting an API', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Write meaningful tests for an endpoint and document an API so another developer can use it without reading your code. Warm-up: what is the first thing a test of GET /users/7 should assert?"},{"heading":"The idea","text":"Tests protect the contract. An endpoint test sends a real request and asserts on the response: first the status code, then the body shape and values, then any important headers. Cover the happy path (valid input succeeds) and the sad paths (missing fields give 422, no token gives 401, absent resource gives 404). Integration tests exercise the route, handler, and database together; unit tests check a single function like a validator in isolation. Documentation is the other half: it publishes the same contract in human-readable form. For each endpoint, state the method and path, the required headers, the request body fields and types, the response body, and the possible status codes. A machine-readable specification such as OpenAPI lets tools generate interactive docs and client libraries from one description. Well-tested and well-documented are two views of the same promise: predictable requests, predictable responses."},{"heading":"Worked examples","text":"A happy-path test: send POST /users with {\"name\": \"Ada\", \"email\": \"ada@x.com\"}; assert status is 201, assert the body has a numeric id, assert body.name equals ''Ada''. A sad-path test: send POST /users with {\"name\": \"\"}; assert status is 422 and body.error.fields.name exists. An auth test: send GET /account with no token; assert status is 401. A documentation entry reads: ''POST /users  - creates a user. Body: {name: string (required), email: string (required)}. Responses: 201 with the created user; 422 if validation fails; 409 if the email exists.'' From that entry alone, another developer can call the endpoint correctly without seeing the handler."},{"heading":"Your turn","text":"1) What should a test assert before checking the body? 2) Write the expected status for POST /users with an empty name. 3) What does an integration test exercise that a unit test may not? 4) Name three things a doc entry should list for an endpoint. 5) What is one benefit of a machine-readable spec like OpenAPI? Answers: 1) The status code. 2) 422 (400 is also acceptable). 3) The route, handler, and database working together. 4) Method and path, request body fields and types, and possible status codes (headers and response body also count). 5) Tools can generate interactive docs and client libraries from it."},{"heading":"Common mistakes & exit ticket","text":"Mistake: testing only the happy path, so error handling silently rots. Mistake: documentation that drifts from the code because it is written once and never updated  - a machine-readable spec checked in tests helps. Exit: (a) Which two path types must tests cover? (b) What does a doc entry publish? Answers: the happy path and the sad (error) paths; the endpoint''s contract  - method, path, request and response shapes, and status codes."}]}'::jsonb, 'A good test asserts on the status code first, then the response body  - the status is the contract''s headline.', 14),
  (14, 'Capstone: design a small REST API', 'reading', '{"sections":[{"heading":"The task","text":"Design a complete REST API for a simple ''reading list'' service, where a user can save books they want to read and mark them as finished. Produce the full endpoint contract on paper  - resources, methods, paths, request and response bodies, and status codes  - as though handing a specification to a teammate who will build it. Do not write framework code; write the design."},{"heading":"The structure to follow","text":"1) Name the resources as plural nouns (think users and books). 2) For each resource, list the CRUD endpoints with method and path, including any nested collection that shows ownership. 3) For every write endpoint, give an example request body in JSON and the exact success status (201 for create, 200 for update). 4) List the error statuses each endpoint can return (401 no token, 403 not your record, 404 missing, 422 invalid input, 409 duplicate). 5) State how a caller authenticates (a bearer token) and note that all traffic is over HTTPS with sensible rate limits. 6) Add one line of documentation per endpoint so a stranger could call it."},{"heading":"A partial model to imitate (a different domain)","text":"Domain: a notes service. Resource: notes. Endpoints: GET /notes lists the caller''s notes (200, requires token or 401). POST /notes creates one; body {\"title\": \"Ideas\", \"text\": \"...\"}; success 201 with the created note; 422 if title is missing. GET /notes/:id reads one (200, or 404 if absent, or 403 if it belongs to another user). PATCH /notes/:id edits (200; 422 on invalid fields). DELETE /notes/:id removes it (204 No Content, idempotent). Auth: send Authorization: Bearer <token>; unauthenticated requests get 401. All endpoints are HTTPS and limited to 100 requests per minute, returning 429 when exceeded. Use this as a template of depth and tone  - do not copy it; your job is the reading-list API above, including the ''finished'' state, perhaps as PATCH /books/:id with body {\"finished\": true}."},{"heading":"Self-check rubric","text":"Check yes to each: every resource is a plural noun and single members are addressed by id; each endpoint states a method, a path, and a success status; write endpoints include an example JSON body; each endpoint lists its plausible error statuses (401/403/404/409/422 as relevant); authentication and transport (bearer token over HTTPS) are stated once and applied throughout; and a one-line description accompanies each endpoint. If all six hold, you have designed a coherent, secure, documented REST API  - the core deliverable of this course."}]}'::jsonb, 'Deliver the design as a contract, not code: for each endpoint give method, path, request body, response body, and status codes.', 16),
  (15, 'Final quiz: APIs and backend development', 'quiz', '{"questions":[{"prompt":"The web''s basic interaction is best described as...","options":["server pushes, client stores","a stateful two-way stream","client request, server response","peer-to-peer broadcast"],"answer":2,"explanation":"HTTP is a stateless request-response cycle: the client asks, the server answers."},{"prompt":"Which status code family indicates the client made an error?","options":["2xx","3xx","4xx","5xx"],"answer":2,"explanation":"4xx codes (like 400, 401, 404) mean the client''s request was at fault."},{"prompt":"A RESTful endpoint to list all products should be...","options":["GET /getProducts","GET /products","POST /products/list","GET /product?all=true"],"answer":1,"explanation":"Plural collection with the GET method: GET /products."},{"prompt":"Which HTTP method is typically NOT idempotent?","options":["GET","PUT","DELETE","POST"],"answer":3,"explanation":"POST usually creates a new resource each time, so repeating it changes the state."},{"prompt":"A valid JSON object uses which quoting for keys and string values?","options":["single quotes","double quotes","no quotes","backticks"],"answer":1,"explanation":"JSON requires double quotes around all keys and string values."},{"prompt":"The variable part of the route GET /orders/:id is captured by...","options":["a query parameter","a path parameter","a response header","the status line"],"answer":1,"explanation":":id is a path parameter that captures the value in that position."},{"prompt":"CRUD''s Create maps to which SQL statement and HTTP method?","options":["SELECT and GET","INSERT and POST","UPDATE and PUT","DELETE and DELETE"],"answer":1,"explanation":"Create is INSERT in SQL and POST over HTTP."},{"prompt":"The safe way to put user input into a SQL query is to...","options":["concatenate it into the string","use bound parameters","encode it as base64","store it in a cookie first"],"answer":1,"explanation":"Bound parameters treat input as data and prevent SQL injection."},{"prompt":"A logged-in user tries an action they lack permission for. The right status is...","options":["401 Unauthorized","403 Forbidden","404 Not Found","200 OK"],"answer":1,"explanation":"403 means authenticated but not allowed; 401 would mean not authenticated at all."},{"prompt":"Input that is syntactically valid JSON but breaks a business rule is best answered with...","options":["200 OK","301 Moved","422 Unprocessable Entity","500 Internal Server Error"],"answer":2,"explanation":"422 signals well-formed input that fails validation rules (400 is also defensible)."},{"prompt":"A client that exceeds its allowed request rate should receive...","options":["429 Too Many Requests","404 Not Found","201 Created","304 Not Modified"],"answer":0,"explanation":"429 Too Many Requests, often with a Retry-After header, signals rate limiting."},{"prompt":"When testing an endpoint, the first thing to assert is usually...","options":["the response time","the status code","the server''s hostname","the JSON indentation"],"answer":1,"explanation":"The status code is the headline of the contract; assert it before the body."}]}'::jsonb, null, 12)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-000000000019' and l.position = v.pos
);
